import { Effect } from "effect";

export interface WorkspaceSummary {
  readonly name: string;
  readonly packages: readonly string[];
}

export const defaultWorkspacePackages = [
  "@bundjil/core",
  "@bundjil/effect-start",
  "@bundjil/eve-effect",
] as const;

export const makeWorkspaceSummary = (
  name = "bundjil"
): Effect.Effect<WorkspaceSummary> =>
  Effect.succeed({
    name,
    packages: defaultWorkspacePackages,
  });
import { assert, it } from "@effect/vitest";
import { Effect } from "effect";

import {
  defaultWorkspacePackages,
  makeWorkspaceSummary,
} from "../src/index.js";

it.effect("creates the default Bundjil workspace summary", () =>
  Effect.gen(function* testDefaultSummary() {
    const summary = yield* makeWorkspaceSummary();

    assert.strictEqual(summary.name, "bundjil");
    assert.deepStrictEqual(summary.packages, defaultWorkspacePackages);
  })
);

it.effect("allows a custom workspace name", () =>
  Effect.gen(function* testCustomName() {
    const summary = yield* makeWorkspaceSummary("example");

    assert.strictEqual(summary.name, "example");
  })
);
# @bundjil/core

Framework-neutral domain primitives and Effect programs for Bundjil, the
personal-agent workspace.

This package is where stable, reusable agent contracts should live: normalized
message envelopes, identities, consent state, task intents, tool contracts, and
pure or Effect-returning programs that do not depend on a specific app
framework or provider transport.

The package currently exports a small workspace summary program so the
workspace has a real Effect-backed package, test suite, and build output.
Future app code should only move logic here when it is clearly reusable across
channels or runtimes.

