import { Schema } from "effect";

export const BundjilWorkspaceStatusQuestion = Schema.NonEmptyString;
export type BundjilWorkspaceStatusQuestion =
  typeof BundjilWorkspaceStatusQuestion.Type;

export const BundjilWorkspaceName = Schema.NonEmptyString.pipe(
  Schema.brand("BundjilWorkspaceName")
);
export type BundjilWorkspaceName = typeof BundjilWorkspaceName.Type;

export const BundjilPackageName = Schema.NonEmptyString.pipe(
  Schema.brand("BundjilPackageName")
);
export type BundjilPackageName = typeof BundjilPackageName.Type;

export const BundjilAgentSummary = Schema.NonEmptyString;
export type BundjilAgentSummary = typeof BundjilAgentSummary.Type;

export const EveMessageCompletedEventTypeValue = "message.completed";

export const EveMessageCompletedEventType = Schema.Literal(
  EveMessageCompletedEventTypeValue
);
export type EveMessageCompletedEventType =
  typeof EveMessageCompletedEventType.Type;

export const EveAssistantStepFinishReason = Schema.Literals([
  "content-filter",
  "error",
  "length",
  "other",
  "stop",
  "tool-calls",
]);
export type EveAssistantStepFinishReason =
  typeof EveAssistantStepFinishReason.Type;

export const EveSessionId = Schema.NonEmptyString.pipe(
  Schema.brand("EveSessionId")
);
export type EveSessionId = typeof EveSessionId.Type;

export const EveTurnId = Schema.NonEmptyString.pipe(Schema.brand("EveTurnId"));
export type EveTurnId = typeof EveTurnId.Type;

export const EveAssistantMessageContent = Schema.String;
export type EveAssistantMessageContent = typeof EveAssistantMessageContent.Type;

export const WorkspaceStatusInput = Schema.Struct({
  question: BundjilWorkspaceStatusQuestion,
});

export type WorkspaceStatusInput = typeof WorkspaceStatusInput.Type;

export const WorkspaceStatusSuccess = Schema.Struct({
  workspaceName: BundjilWorkspaceName,
  packageNames: Schema.Array(BundjilPackageName),
  agentSummary: BundjilAgentSummary,
});

export type WorkspaceStatusSuccess = typeof WorkspaceStatusSuccess.Type;

export type WorkspaceStatusToolInput = WorkspaceStatusInput;

export type WorkspaceStatusToolSuccess = WorkspaceStatusSuccess;
import { makeWorkspaceSummary } from "@bundjil/core";
import { Context, Effect, Layer, Schema } from "effect";

import { BundjilAgentSchemaError } from "../errors.js";
import type { WorkspaceStatusFailure } from "../errors.js";
import { WorkspaceStatusSuccess } from "../schemas.js";
import type {
  WorkspaceStatusInput,
  WorkspaceStatusSuccess as WorkspaceStatusSuccessType,
} from "../schemas.js";

export interface BundjilAgentOperationsShape {
  readonly getWorkspaceStatus: (
    input: WorkspaceStatusInput
  ) => Effect.Effect<WorkspaceStatusSuccessType, WorkspaceStatusFailure>;
}

export class BundjilAgentOperations extends Context.Service<
  BundjilAgentOperations,
  BundjilAgentOperationsShape
>()("@bundjil/eve-effect/BundjilAgentOperations") {}

export const BundjilAgentOperationsLive = Layer.effect(
  BundjilAgentOperations,
  Effect.succeed({
    getWorkspaceStatus: Effect.fn(
      "BundjilAgentOperationsLive.getWorkspaceStatus"
    )((input: WorkspaceStatusInput) =>
      Effect.gen(function* getWorkspaceStatus() {
        const workspace = yield* makeWorkspaceSummary();

        return yield* Schema.decodeUnknownEffect(WorkspaceStatusSuccess)({
          workspaceName: workspace.name,
          packageNames: workspace.packages,
          agentSummary: `Question: ${input.question}. Workspace ${workspace.name} exposes ${workspace.packages.length} packages: ${workspace.packages.join(", ")}.`,
        }).pipe(
          Effect.mapError(
            (cause) =>
              new BundjilAgentSchemaError({
                boundary: "WorkspaceStatusSuccess",
                message: "Unable to decode workspace status success.",
                cause,
              })
          )
        );
      }).pipe(Effect.withSpan("BundjilAgentOperations.getWorkspaceStatus"))
    ),
  })
);

export const BundjilAgentOperationsMemory = (
  workspaceStatus: WorkspaceStatusSuccessType
) =>
  Layer.succeed(BundjilAgentOperations, {
    getWorkspaceStatus: Effect.fn(
      "BundjilAgentOperationsMemory.getWorkspaceStatus"
    )((_input: WorkspaceStatusInput) => Effect.succeed(workspaceStatus)),
  });

export const getWorkspaceStatus = (input: WorkspaceStatusInput) =>
  Effect.gen(function* getWorkspaceStatus() {
    const operations = yield* BundjilAgentOperations;

    return yield* operations.getWorkspaceStatus(input);
  });
