import { Effect, Schema } from "effect";

export const BundjilWorkspaceName = Schema.NonEmptyString.pipe(
  Schema.brand("BundjilWorkspaceName")
);
export type BundjilWorkspaceName = typeof BundjilWorkspaceName.Type;

export const BundjilPackageName = Schema.NonEmptyString.pipe(
  Schema.brand("BundjilPackageName")
);
export type BundjilPackageName = typeof BundjilPackageName.Type;

export const BundjilDefaultWorkspacePackage = Schema.Literals([
  "@bundjil/core",
  "@bundjil/effect-start",
  "@bundjil/eve-effect",
]);
export type BundjilDefaultWorkspacePackage =
  typeof BundjilDefaultWorkspacePackage.Type;

const BundjilDefaultWorkspacePackages = Schema.Tuple([
  Schema.Literal("@bundjil/core"),
  Schema.Literal("@bundjil/effect-start"),
  Schema.Literal("@bundjil/eve-effect"),
]);

const defaultWorkspacePackageInput = [
  "@bundjil/core",
  "@bundjil/effect-start",
  "@bundjil/eve-effect",
] as const;

export const WorkspaceSummary = Schema.Struct({
  name: BundjilWorkspaceName,
  packages: Schema.Array(BundjilPackageName),
});
export type WorkspaceSummary = typeof WorkspaceSummary.Type;

export const makeWorkspaceSummary = (
  name = "bundjil"
): Effect.Effect<WorkspaceSummary, Schema.SchemaError> =>
  Effect.gen(function* makeWorkspaceSummary() {
    const packages = yield* Schema.decodeUnknownEffect(
      BundjilDefaultWorkspacePackages
    )(defaultWorkspacePackageInput);

    return yield* Schema.decodeUnknownEffect(WorkspaceSummary)({
      name,
      packages,
    });
  });
import { assert, it } from "@effect/vitest";
import { Effect, Schema } from "effect";

import {
  BundjilDefaultWorkspacePackage,
  makeWorkspaceSummary,
} from "../src/index.js";

it.effect("creates the default Bundjil workspace summary", () =>
  Effect.gen(function* testDefaultSummary() {
    const summary = yield* makeWorkspaceSummary();

    assert.strictEqual(summary.name, "bundjil");
    assert.deepStrictEqual(summary.packages, [
      "@bundjil/core",
      "@bundjil/effect-start",
      "@bundjil/eve-effect",
    ]);
    assert.isTrue(
      Schema.is(BundjilDefaultWorkspacePackage)(summary.packages[0])
    );
  })
);

it.effect("allows a custom workspace name", () =>
  Effect.gen(function* testCustomName() {
    const summary = yield* makeWorkspaceSummary("example");

    assert.strictEqual(summary.name, "example");
  })
);

it.effect(
  "rejects an empty workspace name through the Effect error channel",
  () =>
    Effect.gen(function* testInvalidWorkspaceName() {
      const error = yield* Effect.flip(makeWorkspaceSummary(""));

      assert.isDefined(error);
    })
);

