import { assert, it } from "@effect/vitest";
import { Effect, Schema } from "effect";

import {
  BundjilAgentOperationsLive,
  BundjilAgentOperationsMemory,
  EveAssistantStepFinishReason,
  EveMessageCompletedEventType,
  EveMessageCompletedEventTypeValue,
  EveSessionId,
  EveTurnId,
  WorkspaceStatusSuccess,
  getWorkspaceStatus,
} from "../src/index.js";

it.effect("decodes canonical Eve completed-event contracts", () =>
  Effect.gen(function* testCompletedEventContracts() {
    assert.strictEqual(
      yield* Schema.decodeUnknownEffect(EveMessageCompletedEventType)(
        EveMessageCompletedEventTypeValue
      ),
      "message.completed"
    );
    assert.deepStrictEqual(
      yield* Effect.forEach(
        ["content-filter", "error", "length", "other", "stop", "tool-calls"],
        (finishReason) =>
          Schema.decodeUnknownEffect(EveAssistantStepFinishReason)(finishReason)
      ),
      ["content-filter", "error", "length", "other", "stop", "tool-calls"]
    );
    assert.strictEqual(
      yield* Schema.decodeUnknownEffect(EveSessionId)("session-private"),
      "session-private"
    );
    assert.strictEqual(
      yield* Schema.decodeUnknownEffect(EveTurnId)("turn-private"),
      "turn-private"
    );
  })
);

it.effect(
  "gets deterministic workspace status from the live Effect service",
  () =>
    Effect.gen(function* testLiveWorkspaceStatus() {
      const status = yield* getWorkspaceStatus({
        question: "What can this workspace do?",
      }).pipe(Effect.provide(BundjilAgentOperationsLive));

      assert.strictEqual(status.workspaceName, "bundjil");
      assert.strictEqual(
        status.packageNames.join(","),
        "@bundjil/core,@bundjil/effect-start,@bundjil/eve-effect"
      );
      assert.include(status.agentSummary, "What can this workspace do?");
      assert.include(status.agentSummary, "@bundjil/core");
    })
);

it.effect("can replace the operation with a memory layer", () =>
  Effect.gen(function* testMemoryWorkspaceStatus() {
    const status = yield* getWorkspaceStatus({
      question: "Use the memory layer.",
    }).pipe(
      Effect.provide(
        BundjilAgentOperationsMemory(
          Schema.decodeUnknownSync(WorkspaceStatusSuccess)({
            workspaceName: "memory-workspace",
            packageNames: ["@bundjil/memory-only"],
            agentSummary: "Memory-backed status for tests.",
          })
        )
      )
    );

    assert.strictEqual(status.workspaceName, "memory-workspace");
    assert.strictEqual(status.packageNames[0], "@bundjil/memory-only");
    assert.strictEqual(status.agentSummary, "Memory-backed status for tests.");
  })
);
import { BundjilDefaultWorkspacePackage } from "@bundjil/core";
import { WorkspaceStatusSuccess } from "@bundjil/eve-effect";
import { assert, it } from "@effect/vitest";
import { Effect, Schema } from "effect";
import type { ToolContext } from "eve/tools";

import workspaceStatusTool, {
  workspaceStatusInputSchema,
  workspaceStatusOutputSchema,
} from "../agent/tools/workspace_status.js";

const unusedToolContext: ToolContext = {
  session: {
    id: "test-session",
    auth: {
      current: null,
      initiator: null,
    },
    turn: {
      id: "test-turn",
      sequence: 0,
    },
  },
  abortSignal: new AbortController().signal,
  callId: "test-call",
  getSandbox: () => Promise.reject(new Error("Sandbox is not used.")),
  getSkill: () => {
    throw new Error("Skills are not used.");
  },
  getToken: () => Promise.reject(new Error("Auth is not used.")),
  requireAuth: () => {
    throw new Error("Auth is not used.");
  },
};

it.effect("executes the Eve tool through the live Effect named operation", () =>
  Effect.gen(function* testWorkspaceStatusTool() {
    const status = yield* Effect.promise(() =>
      Promise.resolve(
        workspaceStatusTool.execute(
          {
            question: "Which packages are available?",
          },
          unusedToolContext
        )
      )
    );

    assert.strictEqual(status.workspaceName, "bundjil");
    assert.strictEqual(
      status.packageNames.join(","),
      "@bundjil/core,@bundjil/effect-start,@bundjil/eve-effect"
    );
    assert.isTrue(
      Schema.is(BundjilDefaultWorkspacePackage)(status.packageNames[0])
    );
    assert.include(status.packageNames.join(","), "@bundjil/eve-effect");
    assert.include(status.agentSummary, "Which packages are available?");
    assert.include(status.agentSummary, "@bundjil/eve-effect");
  })
);

it.effect(
  "uses Effect Schema adapters for Eve input and output validation",
  () =>
    Effect.sync(() => {
      assert.strictEqual(
        workspaceStatusTool.inputSchema,
        workspaceStatusInputSchema
      );
      assert.strictEqual(
        workspaceStatusTool.outputSchema,
        workspaceStatusOutputSchema
      );

      assert.isFunction(workspaceStatusInputSchema["~standard"].validate);
      assert.isFunction(
        workspaceStatusInputSchema["~standard"].jsonSchema.input
      );
      assert.isFunction(workspaceStatusOutputSchema["~standard"].validate);
      assert.isFunction(
        workspaceStatusOutputSchema["~standard"].jsonSchema.output
      );

      assert.deepStrictEqual(
        workspaceStatusInputSchema["~standard"].validate({ question: "" }),
        {
          issues: [
            {
              message: 'Expected a value with a length of at least 1, got ""',
              path: ["question"],
            },
          ],
        }
      );

      const expectedWorkspaceStatus = Schema.decodeUnknownSync(
        WorkspaceStatusSuccess
      )({
        workspaceName: "bundjil",
        packageNames: [
          "@bundjil/core",
          "@bundjil/effect-start",
          "@bundjil/eve-effect",
        ],
        agentSummary: "Workspace status.",
      });

      assert.deepStrictEqual(
        workspaceStatusOutputSchema["~standard"].validate({
          workspaceName: "bundjil",
          packageNames: [
            "@bundjil/core",
            "@bundjil/effect-start",
            "@bundjil/eve-effect",
          ],
          agentSummary: "Workspace status.",
        }),
        {
          value: {
            ...expectedWorkspaceStatus,
          },
        }
      );
    })
);

